# coding: utf-8
"""Twelve source-image reviewed ethics questions; independent answers recorded first."""
import json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')};items=[]
def add(q,stem,conditions,values,reasons,answer,solution,core,knowledge,theories,concept='engineering_ethics',citations=(),law=False,verdicts=None,figure=False):
 r=by[q];assert len(values)==len(reasons)==5
 if verdicts is None:verdicts=['設問条件に一致' if i==answer else '設問条件に不一致' for i in range(1,6)]
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions,choices={str(i):dict(value=v,verdict=j,reason=w) for i,(v,j,w) in enumerate(zip(values,verdicts,reasons),1)},figures='原典画像で問題幹、条件、正誤の向き、全5肢、組合せ表の全セルを確認。設問固有の模式図なし。',ambiguity='',evidence=[f'extracted/pages/{r["source_year_directory"]}/aptitude/page_{p:03}.png' for p in range(int(r['source_page']),int(r['source_page_end'])+1)],core_concept=core,required_knowledge=knowledge,solution=solution,independent_answer=str(answer),answer_reason=solution,learning_points='事実と価値判断、行為の結果と手続を区別し、'+core+'から判断の理由を説明する。',theory_references=['theory:ethics:'+t for t in theories],discipline_id='apt_5',concept_id=concept,classification_reason='原典画像の全条件・肢を確認し、'+core+'を中心とする技術者倫理の問題として分類。',calculation='false',figure=str(figure).lower(),law=str(law).lower(),evaluation=dict(knowledge_novelty='2',reasoning_steps='2',calculation_load='0',figure_reading='1' if figure else '0',difficulty='2',difficulty_reason='専門外の倫理用語・組織手続を理解し、限定語と複数の価値の優先関係を読む必要がある。'),citations=list(citations),foundationality='high',transferability='high'))
add('H24-REG-APT-02','倫理綱領に沿う技術者の行動について、最も不適切な記述を選ぶ。',{'方向':'最も不適切な記述。','対象':'公衆、雇用者、顧客への責任を持つ技術専門職。'},['誠実な対応で専門職の品位・信頼を高める。','不当な対価を直接にも間接にも与えず、求めず、受け取らない。','公衆の安全・健康・福祉又は環境へ害の可能性があれば、即時・無条件に情報を公開する。','人種、性、年齢、地位、所属、思想・宗教等によって差別せず、人権と人格を尊重する。','専門知識と経験を生かして、次世代の技術者・研究者を育てる。'],['専門職の信用は、能力とともに誠実な履行によって支えられる。','不当な利益の授受は判断の公正さを損なう。直接・間接を問わないという趣旨は妥当である。','危険の確認、被害の緊急性、適切な通報先、秘密・個人情報の扱いを検討せず、あらゆる情報を無条件で公表することは適切でない。','人格尊重と公平な取扱いは倫理的な協業の基礎である。','専門職の知識継承と人材育成に沿う。'],3,'1・2・4・5は誠実性、公正、人格尊重、育成の行動である。3は公益を理由に公開の対象・時期・手続の検討を全て省いている。必要な警告や緊急対応は遅らせないが、危険の可能性があることと無条件で全面公開することは同じではない。3を選ぶ。','公益確保と適切な情報開示','公衆への責任、秘密保持の正当理由、事実の確認、差別防止。',['public','disclosure'],citations=['ipej_ethics2011','ipej_ethics2023'],verdicts=['適切','適切','不適切','適切','適切'])
add('H24-REG-APT-12','企業の社会的責任に関わる活動の捉え方について、最も不適切なものを選ぶ。',{'用語':'CSRは企業の社会的責任、CSVは共有価値の創出。','時点':'平成24年度の設問。CSVは2011年の提案を背景とする。'},['災害時に社員へ交通費を支給してボランティアとして派遣するのはCSRの一環となり得る。','社会貢献の結果売上が上がれば販売促進と見なされ、CSRにはなり得ない。','国内販売量に応じ海外経済支援へ資金提供するのはCSRの一環となり得る。','自社製品の廃棄物を有償回収・再資源化して削減するのはCSRの一環となり得る。','受動的な対応にとどまらず企業戦略として共有価値の創出へ取り組む考え方が提唱される。'],['社員の参加を支援して被災社会へ貢献する活動は、社会的責任の一つの取組となる。','社会的効果と企業の経済的効果は両立し得る。売上増加だけを理由にCSRから排除できない。','受益地域が販売地域と一致しなければならないという条件はない。','料金を取ること自体は廃棄物削減の社会的効果を否定しない。','社会課題への対応と競争力を結び付けるCSVの提案は出題時点に存在する。ただしCSVとCSRを同一の定義にしない。'],2,'企業の利益が生じるかどうかだけで社会的責任の活動を判別できない。2の「売上が上がるとCSRではなくなる」という排他的な条件が誤りである。5は社会と企業の両方の価値を生む戦略の提唱について述べるもので、全てのCSRがCSVになるとの意味ではない。','社会的価値と経済的価値の両立','社会的責任、利害関係者、寄付・事業活動・共有価値の区別。',['csr'],concept='standards_ethics',citations=['iso26000','hbs_csv'],verdicts=['適切','不適切','適切','適切','適切'])
add('H25-REG-APT-12','予算制約下のプロジェクト運営で、透明性を備えた最も適切な対応を選ぶ。',{'条件':'経済性とともに活動の透明性に注意する。','E':'実験の遅れで予定期間内の完了が難しくなり、上司へ報告し了承された。'},['良い成果が出るとの確信から予算超過を上司へ報告せず遂行する。','事業継続計画の複数の危機に、対策が安価なものから順に対応する。','費用対効果の順位で計数できない項目は除外し、それを考慮する上司の指示を拒否する。','継続のため必要機器を私費で購入し、予算超過への問題はないとする。','遅延を報告して了承を得たうえで、余る予算を未消化分として計上し返上する。'],['結果への自信は、予算変更の承認と報告を省略する根拠にならない。','安価さだけでは危機の重大性、発生可能性、重要業務への影響と対策の効果を評価できない。','金銭へ換算しにくい安全、信頼、社会的影響も意思決定に必要である。評価法を明示して扱う。','資金の出所を私費にしても、支出・所有・管理を含む透明な組織手続が不要になるわけではない。','遅延の共有と了承、未消化額の記録、不要な支出の回避が透明性に沿う。'],5,'予算は「使い切る」ことを目的とせず、目的に必要な支出を承認された範囲で行う。5は進捗の悪化を共有し、残額を記録して返上する。1と4は手続を省略し、2と3は評価軸を恣意的に狭めるため、最も適切な5を選ぶ。','予算と進捗の説明責任','予算承認、費用と効果、重要性の定性的評価、記録と報告。',['procedure'],citations=['ipej_ethics2023'])
add('H27-REG-APT-06','功利主義・義務・徳などの倫理原理について、最も不適切な記述を選ぶ。',{'前提':'複数の倫理原理が並び立つ。人を単に技術のための手段と扱わないという倫理判断から導入する。'},['直観的判断の根拠へ戻り、倫理原理で批判的に再検討できる。','最大多数の最大幸福、厳守すべき義務、義務以上の有徳さへ注目するなどで原理に違いがある。','諸原理は補完し合うが、唯一正しい原理が存在すべきとの共通見解が技術者倫理にある。','功利主義は動機・有徳さより行為の結果と幸福を重視する。','功利主義には全体の利益のため少数の不利益を我慢させやすいという指摘がある。'],['直観を結論の根拠として固定せず、理由を検討する役割は適切である。','結果、義務、人格という評価対象の違いを述べている。','各原理の観点が異なることから、単一の正しい原理を専門職全体の合意として断定できない。','功利主義は結果を重視する帰結主義の一形態である。','集計上の総利益と、少数者の権利・負担の公平性が衝突し得るという批判である。'],3,'複数の原理は違う問いを立てる。全体への影響、侵害してはならない権利、専門職の人格をそれぞれ調べることで、直観を点検できる。技術者倫理の共通見解として唯一の原理を要求する3が誤りである。5は功利主義への批判を述べたもので、少数者の犠牲を本教材が推奨する意味ではない。','結果・義務・徳による倫理判断','帰結主義と功利主義、義務と人格尊重、徳、負担の分配。',['principles'],citations=['scu_ethics_framework'],verdicts=['適切','適切','不適切','適切','適切'])
add('H29-REG-APT-03','納期を短縮し原価を下げる工程変更の提案を検討する際、4事項の優先順位を選ぶ。',{'状況':'材料の納入不足で遅延が生じ、納入業者が工程の一部変更を条件に早く安く納入できると提案。','表の順':'1番→2番→3番→4番。'},['納期→原価→品質→安全','安全→原価→品質→納期','安全→品質→納期→原価','品質→納期→安全→原価','品質→安全→原価→納期'],['納期と費用を守るため安全と品質の確認を後回しにしている。','安全を先にする点はよいが、仕様・性能へ関わる品質より原価を先にしている。','この提案の条件ではまず安全と必要品質を確保し、残る実行可能な案の納期と費用を検討する。','安全を納期より下にしている。','品質を安全より先にし、残る二事項もこの候補比較での適切な順序と異なる。'],3,'工程を変えても安全と要求品質が確保されるかを先に確認する。その制約を満たす案について納期と原価を比較するので3である。この設問の順位を、全ての契約で納期と費用の関係が常に固定されるという一般法則へ拡張しない。','安全と品質を制約にした工程変更','公衆の安全優先、要求仕様、変更管理、費用と納期の比較。',['public','procedure'],citations=['ipej_ethics2011'],figure=True)
add('H29-REG-APT-07','新技術・新工法の品質問題に対する関係者の対応で、最も適切なものを選ぶ。',{'状況':'公共施設等でデータ虚偽報告が発生。開発者、現場、管理者、評価機関、発注者に専門能力と共通認識が必要。'},['現場で異常が反復するが、開発担当者の電話指示どおり日常的にデータを修正して提出する。','支店で対策会議を開くが期待を伝え、現場だけで解決してから報告するよう指示する。','内部対策フローはあるが組織の倫理欠如を懸念し、会議前日にマスコミへ告発する。','評価機関・団体が横断連携し、類似技術の問題と知見の共有・研修を進める。','民間開発の新技術を全て中止し、全従来工法で巧妙な偽装を前提とする抜き打ち立会検査を標準導入する。'],['担当者の権威は、異常の原因を調べず原記録と異なる報告をする根拠にならない。','会議開催だけでは十分でなく、必要な組織的専門能力と責任を現場へ押し付けている。','緊急性、内部手続の実効性、告発先等を検討した記述がなく、この条件では会議前の報道告発を最適とできない。告発を一律に否定する趣旨ではない。','個別現場の経験を組織・業界の知識として共有し、共通の専門能力を高める再発防止に沿う。','検査強化自体は有用となり得るが、全技術を一律中止する措置は個別のリスク評価を欠き、過大な禁止となる。'],4,'データの真正性を守り、現場と管理者が問題を共有し、評価機関も含めて専門能力を改善する必要がある。4はその学習と再発防止を進める。1・2は責任の転嫁、3は手続の検討不足、5は一律の過大対応であり、4を選ぶ。','個人の誠実性と組織の再発防止','原記録と報告の真正性、ガバナンス、専門能力の共有、比例した対応。',['organization','disclosure'],citations=['ipej_ethics2023','scj_code2013'])
add('H29-REG-APT-15','倫理的意思決定の促進要因と阻害要因を対比した7行のうち、不適切な対比の数を選ぶ。',{'ア':'促進=利他主義、阻害=利己主義。','イ':'促進=希望・勇気、阻害=失望・おそれ。','ウ':'促進=正直・誠実、阻害=自己ぎまん。','エ':'促進=知識・専門能力、阻害=無知。','オ':'促進=公共的志向、阻害=自己中心的志向。','カ':'促進=指示・命令への批判精神、阻害=無批判な受入れ。','キ':'促進=依存的思考、阻害=自律的思考。'},['0','1','2','3','4'],['キで促進と阻害が逆なので0ではない。','キだけが逆の対比で、不適切なものは1件。','ア〜カに追加の不適切行を数える根拠がない。','逆の行はキだけで3件ではない。','逆の行はキだけで4件ではない。'],2,'ア〜カは他者と公衆への配慮、勇気、事実への誠実さ、能力、指示の吟味を促進側へ置く。キだけは自分で理由を検討する自律を阻害側へ置き、他者への依存を促進側へ置いて逆になっている。不適切1件で2を選ぶ。協力や専門家への相談を「依存的思考」と同一視しない。','道徳的自律と無批判な依存','利他性、自己欺瞞、知識不足、指示の吟味、相談と責任放棄の違い。',['obstacles'],citations=['davis_seven_steps'],figure=True)
add('H30-REG-APT-15','公務員倫理の範囲と、予防倫理・志向倫理を区別し、5空欄の組合せを選ぶ。',{'ア':'許認可・補助金等の相手方で、贈与・接待・割り勘のゴルフや旅行などの規制対象。','イ':'倫理規程で示す公務員倫理の狭い範囲。','ウ':'望ましい行動や姿勢まで含む公務員倫理の範囲。','エ':'するなという服務規律を典型とする消極的倫理。','オ':'した方がよいことへ取り組む積極的倫理。','時点':'平成30年度の制度と文章の語句を確認。現在の具体的な適用・例外は人事院資料を別途確認する。'},['利害関係者／狭義／広義／規律／自律','知人／狭義／広義／予防／自律','知人／広義／狭義／規律／志向','利害関係者／狭義／広義／予防／志向','利害関係者／広義／狭義／予防／自律'],['対象と範囲は合うが、対になる技術者倫理の名称は予防と志向である。','アは単なる知人ではなく利害関係者であり、オも志向が適切。','規制対象と広狭の関係が違い、エの名称も違う。','対象、範囲、消極/積極の5対応が全て合う。','広狭が逆で、積極倫理の名称が志向になっていない。'],4,'職務との利害関係を持つ相手を利害関係者と呼ぶ。法・規程による限定された規制は狭義、望ましい姿勢も含めると広義である。悪い行為を防ぐ側面は予防、よりよい行為へ向かう側面は志向で、4を選ぶ。規程の詳細や例外をこの要約だけで実務へ適用しない。','予防倫理と志向倫理の補完','利害関係者、倫理法令の対象、狭義/広義、予防と積極的な社会貢献。',['aspiration'],citations=['jinji_ethics2017','jinji_ethics_qa','fudano_ethics2021'],law=True,figure=True)
add('R01-RET-APT-03','倫理規程・行動規範を制定する狙いに、5記述が含まれるかを判定する。',{'ア':'一般社会と組織との契約について明確に意思表示する。','イ':'組織のメンバーの目指す理想を表す。','ウ':'倫理的行動の実践的な指針を示す。','エ':'将来のメンバーの教育に使う。','オ':'組織自体の在り方を議論する機会を与える。','並び':'ア・イ・ウ・エ・オの順で○/×。'},['○○○○○','○○○○×','○×○○○','○○×○○','○○○×○'],['5項目とも社会への説明、理想、実践、教育、組織の自己点検という目的に含まれる。','制定の議論は組織の在り方を点検する機会でもあり、オを除外できない。','望ましい理想を表明するイを除外できない。','行動の実践的指針を示すウを除外できない。','新たなメンバーを教育するエを除外できない。'],1,'倫理規程は違反者を罰するだけの文書ではない。社会と組織の信頼関係を示し、行動指針と教育の基準を共有し、制定・見直しの議論を通じて組織の目的を点検する。ア〜オは全て狙いに含まれ、1を選ぶ。「契約」はここでは社会的な約束の意味であり、個別の法的契約の成立を断定しない。','倫理規程の社会的・教育的機能','倫理プログラム、理想と実践、教育、組織の継続的な自己点検。',['organization'],citations=['fudano_ethics2021'],figure=True)
add('R02-REG-APT-02','学協会の倫理規程に沿う技術者の行動について、最も不適切な記述を選ぶ。',{'方向':'最も不適切な記述。'},['品質・信頼性・安全・環境への責任を持ち、公衆の安全・健康・福祉を最優先する。','研究・調査の記録を厳正に扱い不正をしないが、顧客から要求があれば多少のデータ修正をしてよい。','属性による差別をせず、人権と人格を尊重する。','不正を防ぐ公正な環境の維持も責務とし、所属組織や技術者コミュニティの環境改善へ参加する。','知識と経験を次世代の技術者・研究者の指導育成へ生かす。'],['専門職が負う技術的責任と公衆への優先的な配慮に沿う。','顧客の望む結論に合わせた変更を正当化する例外はない。客観的な誤記訂正や妥当な処理とは区別する。','人格尊重と公平な取扱いに沿う。','不正防止を個人の心掛けだけに任せず、職務・研究環境を改善する責任を認めている。','人材育成と知識継承の責務に沿う。'],2,'2は前半でデータの厳正な取扱いを述べながら、後半で顧客の要求に基づく不正な変更を許している。真実性は依頼者の都合によって解除されず、2を選ぶ。データを修正する行為全般が不正なのではなく、根拠のある訂正や処理は記録して説明する。','事実に基づく報告と不正な例外の排除','真実性、公衆の優先、データの改ざん、組織の不正防止。',['public','organization'],citations=['ipej_ethics2011','mext_misconduct2014'],verdicts=['適切','不適切','適切','適切','適切'])
add('R05-REG-APT-11','エシックス・テストの4説明へ対応する名称の組合せを選ぶ。',{'ア':'全員が同じ行為をした場合の社会的成立と矛盾を考える。','イ':'影響を受ける側に自分を置いても同じ判断をするか考える。黄金律に基づく。','ウ':'その行為を繰り返して選ぶと自分がどう見られるか考える。','エ':'その行為が新聞等で報道された場合を考える。','補足':'専門家テストは専門職としてどう評価されるかを倫理綱領等で考える。','並び':'ア・イ・ウ・エの順。'},['普遍化可能性／危害／世評／美徳','普遍化可能性／可逆性／美徳／世評','普遍化可能性／可逆性／世評／常識','常識／普遍化可能性／美徳／世評','常識／危害／世評／普遍化可能性'],['アだけは合うが、立場交換は可逆性、反復による人格は美徳、報道は世評である。','全員への適用、立場交換、反復による人格、公開時の評価がそれぞれ対応する。','アとイは合うが、ウは人格を問う美徳で、エは公開を問う世評である。','ウとエは合うが、アは普遍化可能性、イは可逆性である。','全4対応が違う。危害の大小、一般化、立場交換、人格、公開は別の点検である。'],2,'アは一般化したときの矛盾を調べる普遍化可能性、イは当事者の立場を逆にする可逆性である。ウは繰り返す行動が示す人格の美徳、エは公表されたとき説明できるかという世評で2を選ぶ。世評は単に人気を集めることではなく、判断を公開して吟味する道具である。','エシックス・テストの視点の違い','普遍化、黄金律と立場交換、人格、公開と説明可能性、専門職の規範。',['tests'],citations=['davis_seven_steps'],figure=True)
add('R07-REG-APT-03','倫理的な行動・意思決定を阻害し得る5記述の数を選ぶ。',{'導入例':'私利私欲、責任を果たす結果への恐れ、他人のため・今回だけ等の自己欺瞞。','ア':'無知：適切な判断に不可欠な情報の知識がない。','イ':'自己中心的志向：自分の立場だけで判断し客観的な状況分析ができない。','ウ':'微視的視野：限定した範囲の詳細にとらわれる。','エ':'権威の無批判な受入れ：指導者や上司の意向・指示を吟味しない。','オ':'集団思考：十分な批判的考察なしに集団が結論に達する。'},['1','2','3','4','5'],['不可欠な情報の欠如だけでなく、他の4項目も判断を妨げ得る。','立場・視野・権威・集団の吟味不足も対象なので2件ではない。','詳細への固執は細かく調べること一般と違い、周辺への影響を見落とすので3件ではない。','集団で協力すること自体はよいが、批判的考察を省く集団思考も阻害要因である。','5項目全てが事実把握、他者への配慮、視野、自律、吟味を阻害し得る。'],5,'アは情報不足、イは立場の偏り、ウは視野の狭さ、エは判断の放棄、オは集団での吟味不足を表す。いずれも阻害要因となり得るため5件で5を選ぶ。知識を得る努力、細部の調査、専門家への相談、協働そのものを否定する設問ではない。','個人と集団の判断を妨げる要因','必要情報、他者の視点、全体像、権威の点検、集団の批判的検討。',['obstacles'],citations=['davis_seven_steps'])
