(ROOT/'config/authored_batches/S7_010_engineering_ethics.json').write_text(json.dumps(dict(batch_id='S7_010_engineering_ethics',reference_date='2026-10-09',scope='技術者倫理12問。原典12頁の問題幹・限定条件・全5肢・表全セルを確認し、独立解答を先に記録してから公式と照合。公開/秘密・修正/改ざん・事例の優先順位と一般化を区別。',questions=items),ensure_ascii=False,indent=2)+'\n')
